1	package net.minecraft.client.renderer;
2	
3	import net.minecraft.client.Camera;
4	import net.minecraft.client.Minecraft;
5	import net.minecraft.client.multiplayer.ClientLevel;
6	import net.minecraft.client.player.LocalPlayer;
7	import net.minecraft.client.renderer.state.LightmapRenderState;
8	import net.minecraft.util.ARGB;
9	import net.minecraft.util.Mth;
10	import net.minecraft.util.RandomSource;
