14	import net.minecraft.world.effect.MobEffects;
15	import net.minecraft.world.entity.LivingEntity;
16	import org.joml.Vector3f;
17	import org.joml.Vector3fc;
18	
19	public class LightmapRenderStateExtractor {
20	   public static final Vector3fc WHITE = new Vector3f(1.0F, 1.0F, 1.0F);
21	   private boolean needsUpdate;
22	   private final GameRenderer renderer;
23	   private final Minecraft minecraft;
24	   private final RandomSource randomSource = RandomSource.create();
25	   private float blockLightFlicker;
26	
27	   public LightmapRenderStateExtractor(final GameRenderer renderer, final Minecraft minecraft) {
28	      this.renderer = renderer;
29	      this.minecraft = minecraft;
30	   }
31	
32	   public void tick() {
33	      this.blockLightFlicker = this.blockLightFlicker
34	         + (this.randomSource.nextFloat() - this.randomSource.nextFloat()) * this.randomSource.nextFloat() * this.randomSource.nextFloat() * 0.1F;
35	      this.blockLightFlicker *= 0.9F;
36	      this.needsUpdate = true;
