221	   private void prepareQuadShape(
222	      final BlockAndTintGetter level, final BlockState state, final BlockPos pos, final BakedQuad quad, final boolean ambientOcclusion
223	   ) {
224	      float minX = 32.0F;
225	      float minY = 32.0F;
226	      float minZ = 32.0F;
227	      float maxX = -32.0F;
228	      float maxY = -32.0F;
229	      float maxZ = -32.0F;
230	
231	      for (int i = 0; i < 4; i++) {
232	         Vector3fc position = quad.position(i);
233	         float x = position.x();
234	         float y = position.y();
235	         float z = position.z();
236	         minX = Math.min(minX, x);
237	         minY = Math.min(minY, y);
238	         minZ = Math.min(minZ, z);
239	         maxX = Math.max(maxX, x);
240	         maxY = Math.max(maxY, y);
241	         maxZ = Math.max(maxZ, z);
242	      }
243	
244	      if (ambientOcclusion) {
245	         this.faceShape[BlockModelLighter.SizeInfo.WEST.index] = minX;
246	         this.faceShape[BlockModelLighter.SizeInfo.EAST.index] = maxX;
247	         this.faceShape[BlockModelLighter.SizeInfo.DOWN.index] = minY;
248	         this.faceShape[BlockModelLighter.SizeInfo.UP.index] = maxY;
249	         this.faceShape[BlockModelLighter.SizeInfo.NORTH.index] = minZ;
250	         this.faceShape[BlockModelLighter.SizeInfo.SOUTH.index] = maxZ;
251	         this.faceShape[BlockModelLighter.SizeInfo.FLIP_WEST.index] = 1.0F - minX;
252	         this.faceShape[BlockModelLighter.SizeInfo.FLIP_EAST.index] = 1.0F - maxX;
253	         this.faceShape[BlockModelLighter.SizeInfo.FLIP_DOWN.index] = 1.0F - minY;
254	         this.faceShape[BlockModelLighter.SizeInfo.FLIP_UP.index] = 1.0F - maxY;
255	         this.faceShape[BlockModelLighter.SizeInfo.FLIP_NORTH.index] = 1.0F - minZ;
256	         this.faceShape[BlockModelLighter.SizeInfo.FLIP_SOUTH.index] = 1.0F - maxZ;
257	      }
258	
259	      float minEpsilon = 1.0E-4F;
260	      float maxEpsilon = 0.9999F;
261	
262	      this.facePartial = switch (quad.direction()) {
263	         case DOWN, UP -> minX >= 1.0E-4F || minZ >= 1.0E-4F || maxX <= 0.9999F || maxZ <= 0.9999F;
264	         case NORTH, SOUTH -> minX >= 1.0E-4F || minY >= 1.0E-4F || maxX <= 0.9999F || maxY <= 0.9999F;
265	         case WEST, EAST -> minY >= 1.0E-4F || minZ >= 1.0E-4F || maxY <= 0.9999F || maxZ <= 0.9999F;
266	      };
267	
268	      this.faceCubic = switch (quad.direction()) {
269	         case DOWN -> minY == maxY && (minY < 1.0E-4F || state.isCollisionShapeFullBlock(level, pos));
270	         case UP -> minY == maxY && (maxY > 0.9999F || state.isCollisionShapeFullBlock(level, pos));
271	         case NORTH -> minZ == maxZ && (minZ < 1.0E-4F || state.isCollisionShapeFullBlock(level, pos));
272	         case SOUTH -> minZ == maxZ && (maxZ > 0.9999F || state.isCollisionShapeFullBlock(level, pos));
273	         case WEST -> minX == maxX && (minX < 1.0E-4F || state.isCollisionShapeFullBlock(level, pos));
274	         case EAST -> minX == maxX && (maxX > 0.9999F || state.isCollisionShapeFullBlock(level, pos));
275	      };
276	   }
